SourceCode.Declaration:
/// <summary>
/// Class is used to make copy of <c>UPSPriceTermJournalTable</c> records. Should be called from form UPSPriceTermJournalTable.
/// </summary>
final class UPSPriceTermJournalTableCopy
{
    UPSPriceTermJournalTable    upsPriceTermJournalTableOrig;
    FormDataSource              upsPriceTermJournalTable_ds;

    #OCCRetryCount

}

Method.Source:
public void new(UPSPriceTermJournalTable _journalTable, FormDataSource _formDatasource = null)
{
    // Load price term agreement, or reference will change with form datasource.
    this.upsPriceTermJournalTableOrig   = UPSPriceTermJournalTable::find(_journalTable.AgreementId);
    this.upsPriceTermJournalTable_ds    = _formDatasource;
}

public static void main(Args _args)
{
    if (_args && _args.record() && _args.record().TableId == tableNum(UPSPriceTermJournalTable))
    {
        Object upsPriceTermJournalTable_ds = FormDataUtil::getFormDataSource(_args.record());
        UPSPriceTermJournalTableCopy upsPriceTermJournalTableCopy = new UPSPriceTermJournalTableCopy(_args.record(), upsPriceTermJournalTable_ds);

        upsPriceTermJournalTableCopy.run();
    }
    else
    {
        throw error(strFmt("@SYS27147", new DictClass(classNum(UPSPriceTermJournalTableCopy)).name()));
    }
}

private void run()
{
    UPSPriceTermJournalTable    upsPriceTermJournalTableNew;
    UPSPriceTermJournalTrans    upsPriceTermJournalTransNew, upsPriceTermJournalTransOrig;

    try
    {
        ttsbegin;

        upsPriceTermJournalTable_ds.create(true);
        upsPriceTermJournalTableNew = upsPriceTermJournalTable_ds.cursor();

        // Copy table
        upsPriceTermJournalTableNew.InventSiteId    = upsPriceTermJournalTableOrig.InventSiteId;
        upsPriceTermJournalTableNew.ValidFrom       = upsPriceTermJournalTableOrig.ValidFrom;
        upsPriceTermJournalTableNew.ValidTo         = upsPriceTermJournalTableOrig.ValidTo;
        upsPriceTermJournalTableNew.VendCust        = upsPriceTermJournalTableOrig.VendCust;
        upsPriceTermJournalTableNew.Status          = UPSDisabledEnabled::Disabled;

        upsPriceTermJournalTable_ds.write();

        // Copy line
        while select upsPriceTermJournalTransOrig
            where upsPriceTermJournalTransOrig.AgreementId == upsPriceTermJournalTableOrig.AgreementId
        {
            upsPriceTermJournalTransNew.clear();
            upsPriceTermJournalTransNew.initfromUPSPriceTermJournalTrans(upsPriceTermJournalTransOrig);
            upsPriceTermJournalTransNew.initfromUPSPriceTermJournalTable(upsPriceTermJournalTableNew);
            upsPriceTermJournalTransNew.InventDimId = upsPriceTermJournalTransOrig.InventDimId;
            upsPriceTermJournalTransNew.LineNum     = UPSPriceTermJournalTrans::lastLineNum(upsPriceTermJournalTransNew.AgreementId) + 1;
            upsPriceTermJournalTransNew.PricingRule = UPSPricingRule::find(upsPriceTermJournalTransOrig.PricingRule).copy().RecId;
            upsPriceTermJournalTransNew.insert();
        }

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::Error)
    {
        ttsabort;
        Box::stop("@GLS110288");
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }

    if (upsPriceTermJournalTable_ds)
    {
        upsPriceTermJournalTable_ds.executeQuery();
    }
}
